{
  "name": "通用实验相机",
  "name_en": "Generic Laboratory Camera",
  "manufacturer": "",
  "description": "用于采集可见光图像或视频的相机，可在实验中用于样品观察、装置对准、过程监测和图像记录。",
  "description_en": "A camera for acquiring visible-light images or video, used in laboratories for sample observation, instrument alignment, process monitoring, and image recording.",
  "actions": [
    {
      "action_name": "auto-doInitializeDevice",
      "description": "初始化相机设备",
      "description_en": "initialize the camera device"
    },
    {
      "action_name": "auto-doShutdownDevice",
      "description": "关闭相机设备",
      "description_en": "shut down the camera device"
    },
    {
      "action_name": "auto-livePreview",
      "description": "实时预览相机画面",
      "description_en": "show a live preview from the camera"
    },
    {
      "action_name": "auto-start",
      "description": "开始图像采集",
      "description_en": "start image acquisition"
    },
    {
      "action_name": "auto-isCapturing",
      "description": "获取是否正在采集图像",
      "description_en": "get whether image acquisition is in progress"
    },
    {
      "action_name": "auto-stop",
      "description": "停止图像采集",
      "description_en": "stop image acquisition"
    },
    {
      "action_name": "auto-captureLoopSynchronous",
      "description": "以同步循环方式连续采集图像",
      "description_en": "acquire images continuously in a synchronous loop"
    },
    {
      "action_name": "auto-captureFrames",
      "description": "采集指定数量的图像帧",
      "description_en": "capture a specified number of image frames"
    },
    {
      "action_name": "auto-captureLoopThread",
      "description": "在线程中连续采集图像",
      "description_en": "acquire images continuously in a background thread"
    }
  ],
  "tag_hints": [
    "camera imaging",
    "live preview",
    "image acquisition",
    "sample observation",
    "video monitoring",
    "instrument alignment"
  ]
}

